// Blink the on-board RGB LED red once a second and count the blinks
const uint8_t RGB_PIN = 38;   // v1.1 board: the RGB LED's data line is GPIO38 (v1.0: GPIO48)
uint32_t count = 0;

void setup() {
  Serial.begin(115200);
}

void loop() {
  rgbLedWrite(RGB_PIN, 64, 0, 0);   // red at 64 of 255: bright enough at arm's length
  Serial.printf("blink #%lu\n", (unsigned long)count);
  count++;
  delay(500);
  rgbLedWrite(RGB_PIN, 0, 0, 0);    // all three colours off
  delay(500);
}

// Wake, show a blue blink, count the boot, then deep-sleep for 10 s
const uint8_t RGB_PIN = 38;
RTC_DATA_ATTR uint32_t boots = 0;   // RTC memory keeps its value through deep sleep

void setup() {
  Serial.begin(115200);
  boots++;
  rgbLedWrite(RGB_PIN, 0, 0, 32);   // dim blue while awake
  delay(1000);
  rgbLedWrite(RGB_PIN, 0, 0, 0);    // the LED latches its colour: switch it off before sleeping
  Serial.printf("boot #%lu, sleeping 10 s\n", (unsigned long)boots);
  Serial.flush();                   // send the line before the UART powers down
  esp_sleep_enable_timer_wakeup(10ULL * 1000000ULL);
  esp_deep_sleep_start();           // chip about 8 µA; the board's bridge, regulator and power LED still draw
}

void loop() {}                      // never reached: waking from deep sleep restarts setup()

// Turn the RGB LED once round the colour wheel every 4 s and print the hue every second
const uint8_t RGB_PIN = 38;   // v1.1 board: the RGB LED's data line is GPIO38 (v1.0: GPIO48)
const uint8_t LEVEL = 64;     // brightest channel value, 0-255
uint32_t nextPrint = 0;

// hue 0-359 degrees to red, green and blue: six 60-degree sectors, one channel ramps in each
void hueToRgb(uint16_t hue, uint8_t &r, uint8_t &g, uint8_t &b) {
  uint8_t up = (hue % 60) * LEVEL / 60;
  uint8_t down = LEVEL - up;
  switch (hue / 60) {
    case 0: r = LEVEL; g = up; b = 0; break;
    case 1: r = down; g = LEVEL; b = 0; break;
    case 2: r = 0; g = LEVEL; b = up; break;
    case 3: r = 0; g = down; b = LEVEL; break;
    case 4: r = up; g = 0; b = LEVEL; break;
    default: r = LEVEL; g = 0; b = down; break;
  }
}

void setup() {
  Serial.begin(115200);
}

void loop() {
  uint32_t now = millis();
  uint16_t hue = (now % 4000) * 360 / 4000;   // the hue follows millis(), so the wheel keeps time even when loop() is slow
  uint8_t r, g, b;
  hueToRgb(hue, r, g, b);
  rgbLedWrite(RGB_PIN, r, g, b);
  if (now >= nextPrint) {                    // once a second, on time, without delay()
    nextPrint += 1000;
    Serial.printf("hue %u deg\n", hue);
  }
  delay(10);
}

// Join the bench-lab Wi-Fi and serve a page whose links switch the RGB LED
#include <WiFi.h>
#include <WebServer.h>

const char* SSID = "bench-lab";
const char* PASS = "robotics";   // 2.4 GHz networks only: the ESP32-S3 has no 5 GHz radio
const uint8_t RGB_PIN = 38;

WebServer server(80);

void handleRoot() {
  server.send(200, "text/html",
    "<h1>Hello robot</h1><p><a href=\"/on\">LED ON</a> <a href=\"/off\">LED OFF</a></p>");
  Serial.println("GET / -> page sent");
}

void handleOn() {
  rgbLedWrite(RGB_PIN, 0, 64, 0);   // the phone pressed LED ON
  server.send(200, "text/plain", "LED on");
  Serial.println("GET /on -> LED on");
}

void handleOff() {
  rgbLedWrite(RGB_PIN, 0, 0, 0);
  server.send(200, "text/plain", "LED off");
  Serial.println("GET /off -> LED off");
}

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_STA);                      // station mode: join an existing network
  WiFi.begin(SSID, PASS);
  Serial.print("Connecting to bench-lab");
  while (WiFi.status() != WL_CONNECTED) {   // blink blue until the router hands out an address
    rgbLedWrite(RGB_PIN, 0, 0, 64);
    delay(250);
    rgbLedWrite(RGB_PIN, 0, 0, 0);
    delay(250);
    Serial.print('.');
  }
  Serial.println();
  Serial.print("WiFi connected, IP ");
  Serial.println(WiFi.localIP());
  server.on("/", handleRoot);
  server.on("/on", handleOn);
  server.on("/off", handleOff);
  server.begin();
}

// the Wi-Fi stack runs on core 0, setup() and loop() on core 1
void loop() {
  server.handleClient();
}
